const {
  Document, Packer, Paragraph, Table, TableRow, TableCell,
  TextRun, HeadingLevel, AlignmentType, WidthType, BorderStyle,
  ShadingType
} = require("docx");
const fs = require("fs");

// --- Helpers ---
function boldCell(text, shading) {
  const opts = {
    children: [new Paragraph({ children: [new TextRun({ text, bold: true, font: "Calibri", size: 22 })] })],
    width: { size: 50, type: WidthType.PERCENTAGE },
  };
  if (shading) opts.shading = { type: ShadingType.SOLID, color: shading, fill: shading };
  return new TableCell(opts);
}
function textCell(text) {
  return new TableCell({
    children: [new Paragraph({ children: [new TextRun({ text, font: "Calibri", size: 22 })] })],
    width: { size: 50, type: WidthType.PERCENTAGE },
  });
}
function heading(text, level) {
  return new Paragraph({ heading: level, children: [new TextRun({ text, font: "Calibri", bold: true })] });
}
function body(text, opts = {}) {
  return new Paragraph({
    spacing: { after: 120 },
    children: [new TextRun({ text, font: "Calibri", size: 22, ...opts })],
  });
}
function bulletPoint(text) {
  return new Paragraph({
    bullet: { level: 0 },
    spacing: { after: 80 },
    children: [new TextRun({ text, font: "Calibri", size: 22 })],
  });
}

// --- Overview Table ---
const overviewRows = [
  ["Metric", "Value"],
  ["Total Orders", "7"],
  ["Confirmed", "5 (71%)"],
  ["Cancelled", "2 (29%)"],
  ["Grand Total", "$595"],
  ["Confirmed Total", "$477"],
  ["Cancelled Total", "$118"],
];
const headerColor = "4472C4";
const overviewTable = new Table({
  width: { size: 100, type: WidthType.PERCENTAGE },
  rows: overviewRows.map((row, i) => {
    if (i === 0) {
      return new TableRow({
        children: row.map(c => boldCell(c, headerColor)),
      });
    }
    return new TableRow({
      children: [boldCell(row[0]), textCell(row[1])],
    });
  }),
});

// --- Insights ---
const insights = [
  "Average Order Value: Confirmed orders averaged $95.40 ($477 ÷ 5). Cancelled orders averaged $59.00 ($118 ÷ 2). Cancelled orders were lower-value single-item purchases.",
  "Most Popular Product: LogiTech Wireless Mouse M310 — appears in 3 confirmed orders (ORD-5B048F, ORD-D7E869, ORD-CCC96C). Wireless mice in general appear across both confirmed and cancelled orders.",
  "Most Popular Category: Computer peripherals (mice, speakers) dominate, followed by kitchen items (mixing bowls, thermometer) and smart home (desk lamp).",
  "Largest Order: ORD-CCC96C at $201 — the only 3-item order, including the premium Aurora Smart Desk Lamp Pro.",
  "Cancellation Pattern: Both cancelled orders were single-item purchases. Multi-item orders were all confirmed, suggesting higher commitment with bundled purchases.",
  "OXO Mixing Bowl Set appears in 3 confirmed orders — another frequently ordered product alongside the LogiTech mouse.",
];

// --- Build Document ---
const doc = new Document({
  sections: [{
    children: [
      heading("Order Analysis — Maya Chen (2026-09-02)", HeadingLevel.TITLE),
      new Paragraph({ spacing: { after: 200 }, children: [] }),

      heading("Overview", HeadingLevel.HEADING_1),
      new Paragraph({ spacing: { after: 100 }, children: [] }),
      overviewTable,
      new Paragraph({ spacing: { after: 200 }, children: [] }),

      heading("Key Insights", HeadingLevel.HEADING_1),
      new Paragraph({ spacing: { after: 100 }, children: [] }),
      ...insights.map((t, i) => bulletPoint(`${t}`)),
      new Paragraph({ spacing: { after: 200 }, children: [] }),

      heading("Note", HeadingLevel.HEADING_2),
      body("The original order data was sourced from data/maya_chen_orders_2026-09-02.txt."),
    ],
  }],
});

// --- Write File ---
Packer.toBuffer(doc).then((buffer) => {
  fs.writeFileSync("/workspace/data/order_analysis.docx", buffer);
  console.log("✅ Saved to /workspace/data/order_analysis.docx");
});
